sys_script_include.script:
var JinjiACL = Class.create();
JinjiACL.prototype = {
    initialize: function() {},
    type: 'JinjiACL'
};

JinjiACL.shumuKenmu = function(rec) {
	if(rec.yakui_sin == 90 || rec.yakui_kyuu == 90){
		return false;
	}

    var shumuKenmu = rec.kenmu_number;
    var word = "主務";

    if (shumuKenmu == "主務") {
        word == "兼務";
    }

    var gr = new GlideRecord('x_1882833_organi_0_meisai');
    gr.addQuery('sinsei_number', rec.sinsei_number);
    gr.addQuery('name_kanji', rec.name_kanji);
    gr.addQuery('yakui_sin', 90);
    gr.addQuery('kenmu_number', word);
    gr.query();

    var gr2 = new GlideRecord('x_1882833_organi_0_meisai');
    gr2.addQuery('sinsei_number', rec.sinsei_number);
    gr2.addQuery('name_kanji', rec.name_kanji);
    gr2.addQuery('yakui_kyuu', 90);
    gr2.addQuery('kenmu_number', word);
    gr2.query();

    if (gr.hasNext() || gr2.hasNext()) {
		return false;
    }

	return true;

};
